func TestVectorsResumeFrames(t *testing.T) {
	v, _ := loadWireVectors(t)
	req := ResumePoint(v.Resume.ReqPoint)
	f, err := ResumeReqFrame(req)
	if err != nil || hex.EncodeToString(f) != v.Resume.ReqFrame {
		t.Errorf("ResumeReqFrame = %x, %v", f, err)
	}
	if got, err := ParseResumeReq(unhex(t, v.Resume.ReqFrame)); err != nil || got != req {
		t.Errorf("ParseResumeReq = %+v, %v", got, err)
	}

	sp := v.Resume.StartPoint
	s := mustSender(t, v.SessionKeyHex)
	s.next = sp.Seq // the fixture models a sender already at this sequence
	start, err := s.ResumeStartFrame(ResumePoint{Index: sp.Index, Offset: sp.Offset})
	if err != nil || hex.EncodeToString(start) != v.Resume.StartFrame {
		t.Errorf("ResumeStartFrame = %x, %v", start, err)
	}
	if s.NextSeq() != sp.Seq {
		t.Error("RESUME_START consumed a sequence number")
	}
	got, err := ParseResumeStart(unhex(t, v.Resume.StartFrame))
	if err != nil || got != (ResumeStart{Point: ResumePoint{Index: sp.Index, Offset: sp.Offset}, Seq: sp.Seq}) {
		t.Errorf("ParseResumeStart = %+v, %v", got, err)
	}
}

// ---- fragmentation over a 64 KiB peer -----------------------------------------

func TestVectorsFragmentation(t *testing.T) {
	v, _ := loadWireVectors(t)
	fr := v.Fragmentation
	if pb, err := PiecePlainBytes(fr.MaxFrameBytes); err != nil || pb != fr.PieceBytes {
		t.Fatalf("PiecePlainBytes(%d) = %d, %v", fr.MaxFrameBytes, pb, err)
	}
	var bodies [][]byte
	for i, b := range fr.Bodies {
		body := content(b.Size, b.Seed)
		if sha256Hex(body) != b.Sha256 {
			t.Fatalf("body %d: generator mismatch", i)
		}
		bodies = append(bodies, body)
	}

	s := mustSender(t, fr.KeyHex)
	batch, err := s.BatchFrames(metas(fr.Manifest), fr.MaxFrameBytes)
	if err != nil {
		t.Fatal(err)
	}
	if len(batch) != len(fr.BatchFramesHex) {
		t.Fatalf("%d batch frames", len(batch))
	}
	for i := range batch {
		if hex.EncodeToString(batch[i]) != fr.BatchFramesHex[i] {
			t.Errorf("batch frame %d differs", i)
		}
	}
	data, err := s.DataFrames(bodies, nil, fr.MaxFrameBytes)
	if err != nil {
		t.Fatal(err)
	}
	assertStream(t, "fragmentation", data, fr.DataFrames)

	r := mustReceiver(t, fr.KeyHex)
	evs := feedAll(t, r, append(batch, data...))
	var chunkLens []int
	var reassembled [][]byte
	file := 0
	var cur []byte
	for _, ev := range evs {
		switch ev.Kind {
		case EventManifest:
			if len(ev.Manifest) != len(fr.Manifest.Files) {
				t.Fatal("manifest")
			}
		case EventChunk:
			chunkLens = append(chunkLens, len(ev.Chunk))
			cur = append(cur, ev.Chunk...)
		case EventDone:
			if !ev.Verified {
				t.Errorf("file %d not verified", file)
			}
			if got := hex.EncodeToString(chainOf(bodies[file], len(bodies[file]))); got != fr.DoneHashes[file] {
				t.Errorf("file %d doneHash %s", file, got)
			}
			reassembled = append(reassembled, cur)
			cur = nil
			file++
		}
	}
	if !slices.Equal(chunkLens, fr.LogicalChunkLengths) {
		t.Errorf("logical chunks %v, want %v", chunkLens, fr.LogicalChunkLengths)
	}
	for i := range bodies {
		if !bytes.Equal(reassembled[i], bodies[i]) {
			t.Errorf("file %d reassembled wrongly", i)
		}
	}
}

// ---- durable resume across a change of message size ---------------------------

func TestVectorsDurableResume(t *testing.T) {
	v, _ := loadWireVectors(t)
	dr := v.DurableResume
	body := content(dr.Body.Size, dr.Body.Seed)
	if sha256Hex(body) != dr.Body.Sha256 {
		t.Fatal("generator mismatch")
	}
	s := mustSender(t, dr.KeyHex)
	batch, err := s.BatchFrames(metas(dr.Manifest), dr.FirstMaxFrameBytes)
	if err != nil || len(batch) != len(dr.BatchFramesHex) || hex.EncodeToString(batch[0]) != dr.BatchFramesHex[0] {
		t.Fatalf("batch: %v", err)
	}
	first, err := s.DataFrames([][]byte{body}, nil, dr.FirstMaxFrameBytes)
	if err != nil {
		t.Fatal(err)
	}
	delivered, lost := first[:dr.DeliveredFrames.Count], first[dr.DeliveredFrames.Count:]
	assertStream(t, "delivered", delivered, dr.DeliveredFrames)
	assertStream(t, "lost", lost, dr.LostFrames)

	// The receiver durably holds two logical chunks when the transport dies.
	r := mustReceiver(t, dr.KeyHex)
	feedAll(t, r, append(batch, delivered...))
	chain := r.SnapshotChain()
	if hex.EncodeToString(chain[:]) != dr.ChainAtCheckpointHex {
		t.Fatalf("chain at checkpoint %x", chain)
	}
	if got := hex.EncodeToString(chainOf(body, int(dr.Checkpoint.Offset))); got != dr.ChainAtCheckpointHex {
		t.Fatalf("independent chain %s", got)
	}
	cp := ResumePoint(dr.Checkpoint)
	req, err := ResumeReqFrame(cp)
	if err != nil || hex.EncodeToString(req) != dr.ResumeReqHex {
		t.Errorf("resume request %x", req)
	}
	if got, err := ParseResumeReq(req); err != nil || got != cp {
		t.Errorf("ParseResumeReq %+v %v", got, err)
	}

	// The SAME sender, its counter never rewound, refragments for 64 KiB.
	start, err := s.ResumeStartFrame(cp)
	if err != nil || hex.EncodeToString(start) != dr.ResumeStartHex || s.NextSeq() != dr.ResumeSeq {
		t.Fatalf("resume start %x seq %d: %v", start, s.NextSeq(), err)
	}
	resumed, err := s.DataFrames([][]byte{body}, &cp, dr.ResumedMaxFrameBytes)
	if err != nil {
		t.Fatal(err)
	}
	assertStream(t, "resumed", resumed, dr.ResumedFrames)

	rs, err := ParseResumeStart(unhex(t, dr.ResumeStartHex))
	if err != nil || rs.Point != cp || rs.Seq != dr.ResumeSeq {
		t.Fatalf("ParseResumeStart %+v %v", rs, err)
	}
	if err := r.ResumeAt(chain[:], rs.Seq); err != nil {
		t.Fatal(err)
	}
	var tail []byte
	for _, ev := range feedAll(t, r, resumed) {
		switch ev.Kind {
		case EventChunk:
			tail = append(tail, ev.Chunk...)
		case EventDone:
			if !ev.Verified {
				t.Error("resumed file not verified")
			}
		}
	}
	if !bytes.Equal(tail, body[cp.Offset:]) {
		t.Error("resumed bytes differ from the body after the checkpoint")
	}
	if got := hex.EncodeToString(chainOf(body, len(body))); got != dr.DoneHashHex {
		t.Errorf("done hash %s", got)
	}
}

// ---- multi-file checkpoints ---------------------------------------------------

func TestVectorsMultiFileResume(t *testing.T) {
	v, _ := loadWireVectors(t)
	mf := v.MultiFileResume
	var bodies [][]byte
	for _, b := range mf.Bodies {
		bodies = append(bodies, content(b.Size, b.Seed))
	}
	for ci, c := range mf.Cases {
		t.Run(fmt.Sprint(ci), func(t *testing.T) {
			p := ResumePoint(c.Point)
			s := mustSender(t, mf.KeyHex)
			// The fixture models a sender whose counter continues from wherever
			// attempt 1 left it, as a fixed non-zero start.
			s.next = c.SeqAtResume
			start, err := s.ResumeStartFrame(p)
			if err != nil || hex.EncodeToString(start) != c.ResumeStartHex || s.NextSeq() != c.SeqAtResume {
				t.Fatalf("resume start %x: %v", start, err)
			}
			frames, err := s.DataFrames(bodies, &p, mf.MaxFrameBytes)
			if err != nil {
				t.Fatal(err)
			}
			assertStream(t, "case", frames, c.Frames)
			req, err := ResumeReqFrame(p)
			if err != nil || hex.EncodeToString(req) != c.ResumeReqHex {
				t.Errorf("resume request %x", req)
			}

			// A receiver restored to the same checkpoint verifies every DONE.
			r := mustReceiver(t, mf.KeyHex)
			if err := r.ResumeAt(chainOf(bodies[p.Index], int(p.Offset)), c.SeqAtResume); err != nil {
				t.Fatal(err)
			}
			file, got := p.Index, []byte{}
			for _, ev := range feedAll(t, r, frames) {
				switch ev.Kind {
				case EventChunk:
					got = append(got, ev.Chunk...)
				case EventDone:
					from := uint64(0)
					if file == p.Index {
						from = p.Offset
					}
					if !ev.Verified || !bytes.Equal(got, bodies[file][from:]) {
						t.Errorf("file %d: verified=%v, bytes match=%v", file, ev.Verified, bytes.Equal(got, bodies[file][from:]))
					}
					file, got = file+1, []byte{}
				}
			}
			if file != uint64(len(bodies)) {
				t.Errorf("ended at file %d", file)
			}
		})
	}
}

