func mustSignal(t *testing.T, raw []byte) Signal {
	t.Helper()
	s, err := ParseSignal(raw)
	if err != nil {
		t.Fatalf("ParseSignal(%s): %v", raw, err)
	}
	return s
}

func capsSignal(t *testing.T, caps []string) Signal {
	t.Helper()
	raw, err := json.Marshal(map[string][]string{"caps": caps})
	if err != nil {
		t.Fatal(err)
	}
	return mustSignal(t, raw)
}

func TestVectorsCapability(t *testing.T) {
	v, _ := loadWireVectors(t)
	c := v.Capability

	// The hellos are parser inputs here: this package builds none.
	for name, h := range map[string]fxCaps{"web": c.Hello.Web, "native": c.Hello.Native, "linkRoomInactive": c.Hello.LinkRoomInactive} {
		caps, ok := ParseHello(capsSignal(t, h.Caps))
		if !ok || !slices.Equal(caps, h.Caps) {
			t.Errorf("hello %s parsed as %v, %v", name, caps, ok)
		}
		if CapsIncludeLink(caps) != (name != "linkRoomInactive") {
			t.Errorf("hello %s link support wrong", name)
		}
	}
	// Constants only; the cadence itself is W-N18 Phase 2a3.
	if c.Retry.Attempts != CapsAnnounceAttempts || c.Retry.IntervalMs != CapsRetryIntervalMs ||
		c.SettleSeconds != CapsSettleSeconds ||
		c.LastAttemptSeconds*1000 != (CapsAnnounceAttempts-1)*CapsRetryIntervalMs {
		t.Errorf("cadence constants differ: %+v", c.Retry)
	}
	for i, row := range c.Promotion {
		if CapsIncludeLink(row.Caps) != row.Link {
			t.Errorf("promotion %d %v: link=%v", i, row.Caps, row.Link)
		}
	}
	reg := NewPeerCaps()
	reg.Record("p", capsSignal(t, c.Revocation.First.Caps))
	if !reg.SupportsLink("p") {
		t.Fatal("first hello names link/1")
	}
	reg.Record("p", capsSignal(t, c.Revocation.Then.Caps))
	if reg.SupportsLink("p") != c.Revocation.Link {
		t.Error("a later snapshot must revoke link/1")
	}

	for i, raw := range c.NotAHello {
		reg := NewPeerCaps()
		reg.Record("p", capsSignal(t, []string{Capability}))
		s := mustSignal(t, raw)
		if _, ok := ParseHello(s); ok {
			t.Errorf("notAHello %d parsed as a hello", i)
		}
		if reg.Record("p", s) || !reg.SupportsLink("p") {
			t.Errorf("notAHello %d disturbed the earlier announcement", i)
		}
	}
	for i, row := range c.Role {
		want := map[string]string{"initiator": "initiator", "responder": "responder"}[row.Role]
		if got := LinkRole(row.Self, row.Peer).String(); got != want {
			t.Errorf("role %d: %s, want %s", i, got, row.Role)
		}
	}

	pl := c.ProvenLink
	signal := mustSignal(t, pl.Signal)
	silent := NewPeerCaps()
	if silent.Record("p", signal) {
		t.Error("an establishment frame is not a hello")
	}
	if !silent.RecordProvenLink("p", signal) {
		t.Error("a link frame must stand in for a silent peer's hello")
	}
	if got, _ := silent.Announced("p"); !slices.Equal(got, pl.Caps) || !silent.SupportsLink("p") {
		t.Errorf("proven announcement %v", got)
	}
	stated := NewPeerCaps()
	stated.Record("p", capsSignal(t, pl.DoesNotOverrule.Caps))
	if stated.RecordProvenLink("p", signal) || stated.SupportsLink("p") {
		t.Error("a link frame overruled a stated announcement")
	}
}

