func TestVectorsLinkConstants(t *testing.T) {
	v, _ := loadWireVectors(t)
	l := v.Link
	if l.Capability != Capability || !slices.Equal(l.ChannelLabels, ChannelLabels[:]) || l.AuthTagLength != LinkAuthTagLength {
		t.Errorf("capability %q labels %v tag %d", l.Capability, l.ChannelLabels, l.AuthTagLength)
	}
	// Values only. Nothing in this package enforces them.
	d := l.Deadlines
	for name, pair := range map[string][2]int{
		"captureMaxBytes": {l.CaptureMaxBytes, CaptureMaxBytes}, "heldSignalMax": {l.HeldSignalMax, HeldSignalMax},
		"maxCandidateProgress": {l.MaxCandidateProgress, MaxCandidateProgress},
		"noProgressMs":         {d.NoProgressMs, NoProgressMs}, "setupHardCapMs": {d.SetupHardCapMs, SetupHardCapMs},
		"keyRevealMs": {d.KeyRevealMs, KeyRevealMs}, "handshakeDeadlineMs": {d.HandshakeDeadlineMs, HandshakeDeadlineMs},
		"linkAuthMs": {d.LinkAuthMs, LinkAuthMs}, "linkRequestMs": {d.LinkRequestMs, LinkRequestMs},
		"linkRequestRetryMs": {d.LinkRequestRetryMs, LinkRequestRetryMs}, "recoveryWindowMs": {d.RecoveryWindowMs, RecoveryWindowMs},
		"recoveryRetryMs":  {d.RecoveryRetryMs, RecoveryRetryMs},
		"flow.windowBytes": {l.Flow.WindowBytes, FlowWindowBytes}, "flow.ackIntervalBytes": {l.Flow.AckIntervalBytes, FlowAckIntervalBytes},
		"textSession.maxMessages": {l.TextSession.MaxMessages, TextSessionMaxMessages},
		"textSession.maxBytes":    {l.TextSession.MaxBytes, TextSessionMaxBytes},
		"textSession.burst":       {l.TextSession.Burst, TextRateBurst}, "textSession.perSecond": {l.TextSession.PerSecond, TextRatePerSecond},
		"textSession.sendBufferMax": {l.TextSession.SendBufferMax, TextSendBufferMax},
		"textSession.idleMs":        {l.TextSession.IdleMs, TextIdleMs}, "textSession.historyMax": {l.TextSession.HistoryMax, TextHistoryMax},
		"leave.maxAttempts": {l.Leave.MaxAttempts, LeaveMaxAttempts},
	} {
		if pair[0] != pair[1] {
			t.Errorf("%s: fixture %d, Go %d", name, pair[0], pair[1])
		}
	}
	ch := l.ControlHex
	for name, c := range map[string]struct {
		fixture string
		goByte  byte
	}{
		"accept": {ch.Accept, CtrlAccept}, "reject": {ch.Reject, CtrlReject}, "complete": {ch.Complete, CtrlComplete},
		"busy": {ch.Busy, CtrlBusy}, "batchAbort": {ch.BatchAbort, CtrlBatchAbort},
		"textRequest": {ch.TextRequest, CtrlTextRequest}, "textEnd": {ch.TextEnd, CtrlTextEnd},
	} {
		if hex.EncodeToString([]byte{c.goByte}) != c.fixture {
			t.Errorf("controlHex.%s = %s, Go %02x", name, c.fixture, c.goByte)
		}
	}
}

func TestVectorsLinkLifecycleAndFrameClass(t *testing.T) {
	v, _ := loadWireVectors(t)
	lc := v.Link.Lifecycle
	for i, row := range lc.File {
		c, ok := FileLifecycle(unhex(t, row.FrameHex))
		if ok != (row.Kind != nil) || (ok && c.String() != *row.Kind) {
			t.Errorf("file lifecycle %d (%s): %v %v", i, row.FrameHex, c, ok)
		}
	}
	for i, row := range lc.Text {
		c, ok := TextLifecycle(unhex(t, row.FrameHex))
		if ok != (row.Kind != nil) || (ok && c.String() != *row.Kind) {
			t.Errorf("text lifecycle %d (%s): %v %v", i, row.FrameHex, c, ok)
		}
	}
	for i, row := range lc.TextFrame {
		if IsTextFrame(unhex(t, row.FrameHex)) != row.IsTextFrame {
			t.Errorf("textFrame %d: want %v", i, row.IsTextFrame)
		}
	}
	for _, row := range v.Link.FrameClass {
		class, control := ClassifyFileFrame(unhex(t, row.FrameHex))
		if class.String() != row.Class {
			t.Errorf("%s: class %s, want %s", row.Label, class, row.Class)
		}
		if row.Control != "" && control.String() != row.Control {
			t.Errorf("%s: control %s, want %s", row.Label, control, row.Control)
		}
		if row.Control == "" && class == ClassLifecycle {
			t.Errorf("%s: lifecycle row without a control", row.Label)
		}
	}
}

func TestVectorsLinkAuthPayload(t *testing.T) {
	v, _ := loadWireVectors(t)
	for _, row := range v.Link.AuthPayload {
		f, err := AuthFieldsOf(mustSignal(t, row.Signal))
		if err != nil {
			t.Errorf("%s: %v", row.Label, err)
			continue
		}
		p, err := AuthPayload(f)
		if err != nil || hex.EncodeToString([]byte(p)) != row.PayloadUtf8Hex {
			t.Errorf("%s: payload %q, %v", row.Label, p, err)
		}
		if (row.PayloadASCII != nil) != isASCIIString(p) || (row.PayloadASCII != nil && *row.PayloadASCII != p) {
			t.Errorf("%s: payloadAscii disagrees", row.Label)
		}
	}
}

func isASCIIString(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

func TestVectorsLinkLeavePayload(t *testing.T) {
	v, _ := loadWireVectors(t)
	skipped := 0
	for _, row := range v.Link.LinkLeavePayload {
		from, to := utf16.Decode(row.FromUtf16), utf16.Decode(row.ToUtf16)
		if hasLoneSurrogate(row.FromUtf16) || hasLoneSurrogate(row.ToUtf16) {
			// A Go string is UTF-8 and cannot hold a lone UTF-16 surrogate.
			// Exactly one row is allowed to be unrepresentable, and only this
			// one, flagged as such by the fixture itself.
			if row.Label != "unpaired high surrogate" || row.SwiftRepresentable == nil || *row.SwiftRepresentable {
				t.Errorf("%s: an unrepresentable row that is not the flagged one", row.Label)
			}
			skipped++
			continue
		}
		p, err := LinkLeavePayload(string(from), string(to))
		if err != nil || hex.EncodeToString([]byte(p)) != row.PayloadUtf8Hex {
			t.Errorf("%s: payload %q, %v", row.Label, p, err)
		}
		if (row.PayloadASCII != nil) != isASCIIString(p) || (row.PayloadASCII != nil && *row.PayloadASCII != p) {
			t.Errorf("%s: payloadAscii disagrees", row.Label)
		}
	}
	if skipped != 1 {
		t.Errorf("skipped %d unrepresentable rows, want exactly 1", skipped)
	}
}

func hasLoneSurrogate(u []uint16) bool {
	for i := 0; i < len(u); i++ {
		switch {
		case u[i] >= 0xD800 && u[i] <= 0xDBFF:
			if i+1 >= len(u) || u[i+1] < 0xDC00 || u[i+1] > 0xDFFF {
				return true
			}
			i++
		case u[i] >= 0xDC00 && u[i] <= 0xDFFF:
			return true
		}
	}
	return false
}

func TestVectorsLinkLeave(t *testing.T) {
	v, _ := loadWireVectors(t)
	lv := v.Link.Leave
	key := unhex(t, lv.KeyHex)
	if p, err := LinkLeavePayload(lv.From, lv.To); err != nil || p != lv.Payload {
		t.Errorf("payload %q", p)
	}
	tag, err := SignLeave(key, lv.From, lv.To)
	if err != nil || tag != lv.Tag || len(tag) != lv.TagLength || lv.TagLength != LinkAuthTagLength {
		t.Errorf("SignLeave = %q, %v", tag, err)
	}
	if !VerifyLeave(key, lv.From, lv.To, lv.Tag) {
		t.Error("the genuine leave does not verify")
	}
	if rev, _ := SignLeave(key, lv.To, lv.From); rev != lv.ReversedTag {
		t.Errorf("reversed tag %q", rev)
	}
	if VerifyLeave(key, lv.From, lv.To, lv.ReversedTag) {
		t.Error("a reflected leave verified")
	}
	for _, row := range lv.Shapes {
		auth, ok := LeaveAuth(mustSignal(t, row.Signal))
		if ok != row.Accepted {
			t.Errorf("%s: shape accepted=%v, want %v", row.Label, ok, row.Accepted)
			continue
		}
		if !ok {
			continue
		}
		want := row.Verifies == nil || *row.Verifies
		if VerifyLeave(key, lv.From, lv.To, auth) != want {
			t.Errorf("%s: verifies != %v", row.Label, want)
		}
	}
}

func compact(t *testing.T, raw []byte) string {
	t.Helper()
	var b bytes.Buffer
	if err := json.Compact(&b, raw); err != nil {
		t.Fatal(err)
	}
	return b.String()
}

func TestVectorsLinkSignals(t *testing.T) {
	v, _ := loadWireVectors(t)
	sg := v.Link.Signals
	leave, err := LeaveSignal(v.Link.Leave.Tag)
	if err != nil {
		t.Fatal(err)
	}
	for name, pair := range map[string][2]string{
		"request": {string(RequestSignal()), compact(t, sg.Request)},
		"busy":    {string(BusySignal()), compact(t, sg.Busy)},
		"leave":   {string(leave), compact(t, sg.Leave)},
	} {
		if pair[0] != pair[1] {
			t.Errorf("%s signal %s, fixture %s", name, pair[0], pair[1])
		}
	}
	if !IsLinkRequest(mustSignal(t, RequestSignal())) || SignalGeneration(mustSignal(t, BusySignal())) != GenerationLink {
		t.Error("constructed signals do not classify as themselves")
	}
	if _, ok := LeaveAuth(mustSignal(t, leave)); !ok {
		t.Error("the constructed leave is not a leave")
	}
	for i, row := range sg.Generation {
		if got := SignalGeneration(mustSignal(t, row.Signal)).String(); got != row.Generation {
			t.Errorf("generation %d %s: %s, want %s", i, row.Signal, got, row.Generation)
		}
	}
	for i, row := range sg.IsLinkOffer {
		if IsLinkOffer(mustSignal(t, row.Signal)) != row.Expected {
			t.Errorf("isLinkOffer %d %s: want %v", i, row.Signal, row.Expected)
		}
	}
	for i, row := range sg.IsLinkRequest {
		if IsLinkRequest(mustSignal(t, row.Signal)) != row.Expected {
			t.Errorf("isLinkRequest %d %s: want %v", i, row.Signal, row.Expected)
		}
	}
}

// ---- bounds -------------------------------------------------------------------

// manifestOfPayload builds a manifest whose encoded plaintext is exactly n
// bytes, from ASCII names of 1..MaxNameBytes. An entry with a name of L bytes
// and size 0 encodes as {"name":"…","size":0}, L+20 bytes; entries are joined
// by commas inside {"files":[…]}, 12 bytes.
func manifestOfPayload(t *testing.T, n int) []FileMeta {
	t.Helper()
	k := (n - 12 + 1 + (MaxNameBytes + 21) - 1) / (MaxNameBytes + 21)
	names := n - 12 - (k - 1) - 20*k
	files := make([]FileMeta, k)
	for i := range files {
		l := min(names-(k-1-i), MaxNameBytes)
		files[i] = FileMeta{Name: strings.Repeat("x", l)}
		names -= l
	}
	b, err := EncodeManifest(files)
	if err != nil || len(b) != n || names != 0 {
		t.Fatalf("built a %d-byte manifest, want %d: %v", len(b), n, err)
	}
	return files
}

func TestVectorsLinkBounds(t *testing.T) {
	v, _ := loadWireVectors(t)
	b := v.Link.Bounds
	for _, row := range b.PiecePlainBytes {
		pb, err := PiecePlainBytes(row.MaxFrameBytes)
		if row.PieceBytes == nil {
			if !errors.Is(err, ErrPieceTooSmall) {
				t.Errorf("PiecePlainBytes(%d) = %d, want refusal", row.MaxFrameBytes, pb)
			}
		} else if err != nil || pb != *row.PieceBytes {
			t.Errorf("PiecePlainBytes(%d) = %d, %v; want %d", row.MaxFrameBytes, pb, err, *row.PieceBytes)
		}
	}
	for _, row := range b.TextPlainLimit {
		if got := TextPlainLimit(row.MaxFrameBytes); got != row.Limit {
			t.Errorf("TextPlainLimit(%d) = %d, want %d", row.MaxFrameBytes, got, row.Limit)
		}
	}
	for _, row := range b.ManifestCiphertext {
		files := manifestOfPayload(t, row.PayloadBytes)
		s := mustSender(t, v.SessionKeyHex)
		frames, err := s.BatchFrames(files, 262144)
		if (err == nil) != row.Accepted {
			t.Errorf("manifest payload %d: err=%v, want accepted=%v", row.PayloadBytes, err, row.Accepted)
		}
		if err != nil && (s.NextSeq() != 0 || frames != nil) {
			t.Errorf("manifest payload %d: a refused manifest spent a sequence number", row.PayloadBytes)
		}
	}
	for _, row := range b.ManifestFileCount {
		files := make([]FileMeta, row.Count)
		for i := range files {
			files[i] = FileMeta{Name: "f", Size: 1}
		}
		_, encErr := EncodeManifest(files)
		plain := `{"files":[` + strings.TrimSuffix(strings.Repeat(`{"name":"f","size":1},`, row.Count), ",") + `]}`
		_, decErr := DecodeManifest([]byte(plain))
		if (encErr == nil) != row.Accepted || (decErr == nil) != row.Accepted {
			t.Errorf("file count %d: encode %v decode %v, want accepted=%v", row.Count, encErr, decErr, row.Accepted)
		}
	}
	for _, row := range b.ManifestNameBytes {
		name := strings.Repeat("n", row.NameBytes)
		_, encErr := EncodeManifest([]FileMeta{{Name: name}})
		_, decErr := DecodeManifest([]byte(`{"files":[{"name":"` + name + `","size":0}]}`))
		pathBody := `{"files":[{"name":"n","size":0,"path":"` + name + `"}]}`
		_, pathErr := DecodeManifest([]byte(pathBody))
		if (encErr == nil) != row.Accepted || (decErr == nil) != row.Accepted {
			t.Errorf("name bytes %d: encode %v decode %v, want accepted=%v", row.NameBytes, encErr, decErr, row.Accepted)
		}
		// A path shares the byte bound but may be empty.
		if (pathErr == nil) != (row.NameBytes <= MaxNameBytes) {
			t.Errorf("path bytes %d: %v", row.NameBytes, pathErr)
		}
	}
	for _, row := range b.AdvanceAck {
		if got := AdvanceAck(row.Acked, row.Sent, row.Candidate); got != row.Result {
			t.Errorf("AdvanceAck(%d, %d, %v) = %d, want %d", row.Acked, row.Sent, row.Candidate, got, row.Result)
		}
	}
	for i, row := range b.ResumePoint {
		p := ResumePoint(row.Point)
		if ResumeAligned(p, row.Sizes) != row.Aligned || ResumeInRange(p, row.Sizes) != row.InRange {
			t.Errorf("resume point %d %+v in %v", i, p, row.Sizes)
		}
	}
}
